package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootCurrentReadScopeTest {
 @Test public void exactlyThreeIndependentReadSlots(){assertTrue(RootCurrentReadScope.ACTIVE);assertEquals(3,RootCurrentReadScope.MAX_FRAMES);assertEquals(15,RootCurrentReadScope.SOURCE_TASK_ID);Set<String> slots=new HashSet<>();for(int i=1;i<=3;i++)assertTrue(slots.add(RootCurrentReadScope.slot(i)));assertEquals(Set.of("READ_1","READ_2","READ_3"),slots);for(int i:new int[]{-1,0,4,Integer.MAX_VALUE})assertThrows(SecurityException.class,()->RootCurrentReadScope.slot(i));}
 @Test public void original180sAdmission(){long s=RootCurrentReadScope.STARTS_UTC,e=RootCurrentReadScope.EXPIRES_UTC;assertFalse(RootCurrentReadScope.current(s-1));assertTrue(RootCurrentReadScope.current(s));assertFalse(RootCurrentReadScope.current(e));assertTrue(RootCurrentReadScope.admissionCurrent(e-180001));assertFalse(RootCurrentReadScope.admissionCurrent(e-180000));assertEquals(181000,RootCurrentReadScope.sessionDeadline(1000,s));}
 @Test public void readDeadlineCannotExtendParentOrWindow(){long u=RootCurrentReadScope.STARTS_UTC;assertEquals(91000,RootCurrentReadScope.deadline(1000,u,181000));assertEquals(1500,RootCurrentReadScope.deadline(1000,u,1500));assertEquals(1001,RootCurrentReadScope.deadline(1000,RootCurrentReadScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidTimesFailClosed(){long u=RootCurrentReadScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootCurrentReadScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootCurrentReadScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootCurrentReadScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootCurrentReadScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootCurrentReadScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void namespaceNeverReusesPriorScopes(){assertNotEquals(RootBoundedBusinessScope.DIRECTORY,RootCurrentReadScope.DIRECTORY);assertNotEquals(RootImageSeriesScope.DIRECTORY,RootCurrentReadScope.DIRECTORY);assertThrows(SecurityException.class,()->RootCurrentReadScope.store(null,1));assertNotEquals(RootReturnReadScope.DIRECTORY,RootCurrentReadScope.DIRECTORY);}
 @Test public void invalidMetadataBeforeAnyWrite()throws Exception{var st=RootCurrentReadScope.store(Path.of("unused"),1);assertThrows(SecurityException.class,()->st.burn("invalid","safe"));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));}
 @Test public void durableReadOnlyNoReturnTapOrRecoveryPrimitive()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootCurrentReadScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootCurrentReadScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("burnReturn"));assertFalse(s.contains("\"RETURN\""));assertFalse(s.contains("burnAction"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=3 maxTap=0 maxReturn=0"));}
}
